import { useRef } from "react";
import { toast } from "react-toastify";
import { MdInfoOutline } from "react-icons/md";
import CustomTooltip from "../Tooltip/CustomTooltip";

const FileLoader = ({
  LoadProductsThroughLoaderFile,
  format,
  disable = false,
  placement = "top",
  allowQuantity = true,
  noteText = "",
  mode = "product", 
  tooltipHeaderText = "You can load the text file and it should be in following format:",

}) => {
  const fileInputRef = useRef(null);

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const fileName = file.name;
    const ext = fileName.substring(fileName.lastIndexOf(".") + 1).toLowerCase();
    const isText = file.type.match(/text.*/);
    const isCsv = file.type === "application/vnd.ms-excel";

    if ((isText || isCsv) && (ext === "csv" || ext === "txt")) {
      // Clear the input so the same file can be re-selected later
      fileInputRef.current.value = null;
      handleUpload(file); // Pass the file to parent handler
    } else {
      toast.error("Please select a valid CSV or txt file.");
      fileInputRef.current.value = null;
    }
  };

  //File Loader Section
  const handleUpload = (file) => {
    const reader = new FileReader();

    reader.onload = function (e) {
      const rows = e.target.result.split(/\r?\n/);
      let listOfObjects = [];

      if (mode === "giftCard") {
        // Accepts: CardNumber,Remarks OR just CardNumber
        for (let i = 0; i < rows.length; i++) {
          const row = rows[i].trim();
          if (!row) continue; 
          const cells = row.split(",");
          const firstCell = cells[0]?.trim();
          if (!firstCell) continue;
          const numericCardNumber = firstCell.replace(/\D/g, "");
          if (!numericCardNumber) {
            continue; 
          }
          if (numericCardNumber.length > 8) {
            toast.error(`Card number ${numericCardNumber} exceeds 8 digits limit. Skipping this row.`);
            continue;
          }
          const remarks = cells[1]?.trim() || "";
          const singleObj = {
            cardNumber: numericCardNumber,
            remarks: remarks,
          };
          listOfObjects.push(singleObj);
        }

        // Remove duplicates (keep first occurrence)
        listOfObjects = Object.values(
          listOfObjects.reduce((acc, curr) => {
            if (!acc[curr.cardNumber]) {
              acc[curr.cardNumber] = { ...curr };
            }
            return acc;
          }, {})
        );
      } else {
        // Product mode: Original functionality preserved
        for (let i = 0; i < rows.length; i++) {
          const row = rows[i].trim();
          if (!row) continue; // Skip empty rows
          
          const cells = row.split(",");
          
          if (cells.length > 1 || !allowQuantity) {
            const singleObj = {
              productCode: cells[0].toUpperCase().trim(),
              qty: allowQuantity
                ? parseFloat(
                    cells[1]?.trim() < 0
                      ? parseFloat(cells[1].trim()) * -1
                      : cells[1]?.trim()
                  ) || 0
                : cells[1] == null
                ? ""
                : parseFloat(cells[1]?.trim() || 0),
              amount:
                cells[2] == null
                  ? ""
                  : parseFloat(
                      cells[2]?.trim() < 0
                        ? parseFloat(cells[2].trim()) * -1
                        : cells[2]?.trim()
                    ) || 0,
            };
            listOfObjects.push(singleObj);
          }
        }

        // Merge qty by Code
        listOfObjects = Object.values(
          listOfObjects.reduce((acc, curr) => {
            if (acc[curr.productCode]) {
              acc[curr.productCode].qty += curr.qty;
            } else {
              acc[curr.productCode] = { ...curr };
            }
            return acc;
          }, {})
        );
      }

      if (listOfObjects.length === 0) {
        toast.error(
          mode === "giftCard"
            ? "The uploaded file contains no valid card numbers to load."
            : "The uploaded file contains no valid item to load."
        );
        return;
      }

      if (listOfObjects.length <= 1000) {
        LoadProductsThroughLoaderFile(listOfObjects, 0);
      } else {
        toast.error(
          `You can't load more than 1000 ${
            mode === "giftCard" ? "gift cards" : "items"
          } at a time via text/csv file`
        );
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="fileLoaderComponent">
      <label htmlFor="grnFile" className="fileLoaderLabel">
        Load File:
      </label>
      <input
        type="file"
        id="grnFile"
        ref={fileInputRef}
        accept=".csv,.txt"
        onChange={handleFileChange}
        className="fileLoaderInput"
        disabled={disable}
      />
      <CustomTooltip body={
          <>
            {tooltipHeaderText}
            <br />
            <b>{format}</b>
            <br />
            {noteText === "" ? (
              <>
                <b>Note:</b> Each Item must be in separate line.
              </>
            ) : (
              <>
                <b>Note:</b> {noteText}
              </>
            )}
          </>
        }
        placement={placement}
      >
        <MdInfoOutline />
      </CustomTooltip>      
    </div>
  );
};

export default FileLoader;
