import Dexie from "dexie";
// Transaction Database for offline transactions
export const dbTransaction = new Dexie("TransactionDB");
dbTransaction.version(1).stores({
  grn: "++localGrnId,syncStatus,grnId,shopId",
  sales: "++localSaleId,syncStatus,shopId,isValidationFailed,isFetched",
  saleReceiptNumber: "[shopId+registerId],shopId,registerId",
  salesHolding: "++localSaleId,syncStatus,shopId,registerId",
  salesHoldingReceiptNumber: "[shopId+registerId],shopId,registerId",
});

// ==================== Transaction Database Helper Functions ====================

export const addTransactionData = async (tableName, record) => {
  return await dbTransaction[tableName].add(record);
};

export const deleteTransactionData = async (tableName, primaryKey) => {
  return await dbTransaction[tableName].delete(primaryKey);
};

export const clearTransactionTable = async (tableName) => {
  return await dbTransaction[tableName].clear();
};

export const getTransactionByLocalId = async (tableName, localId) => {
  return await dbTransaction[tableName].get(localId);
};

export const updateTransactionSyncStatus = async (
  tableName,
  localId,
  syncStatus
) => {
  return await dbTransaction[tableName]
    .where(getTransactionPrimaryKey(tableName))
    .equals(localId)
    .modify({ syncStatus: syncStatus });
};

const getTransactionPrimaryKey = (tableName) => {
  const primaryKeys = {
    grn: "localGrnId",
    poMaster: "localPOId",
    sales: "localSaleId",
    saleReceiptNumber: "[shopId+registerId]",
    grnMatrix: "localGrnId",
    salesHolding: "localSaleId",
    salesHoldingReceiptNumber: "[shopId+registerId]",
  };
  return primaryKeys[tableName];
};

export const saveSaleReceiptNumber = async (
  shopId,
  registerId,
  localSaleId
) => {
  const existingRecord = await dbTransaction.saleReceiptNumber
    .where("[shopId+registerId]")
    .equals([parseInt(shopId), parseInt(registerId)])
    .first();

  const receiptData = {
    shopId: parseInt(shopId),
    registerId: parseInt(registerId),
    localSaleId: parseInt(localSaleId),
  };

  if (existingRecord) {
    // Update existing record
    await dbTransaction.saleReceiptNumber.put(receiptData);
  } else {
    // Add new record
    await dbTransaction.saleReceiptNumber.add(receiptData);
  }

  return receiptData;
};

export const getSaleReceiptNumber = async (shopId, registerId) => {
  return await dbTransaction.saleReceiptNumber
    .where("[shopId+registerId]")
    .equals([parseInt(shopId), parseInt(registerId)])
    .first();
};

export const getTransactionTableData = async (tableName) => {
  return await dbTransaction[tableName].toArray();
};

export const saveSaleHoldingReceiptNumber = async (
  shopId,
  registerId,
  localSaleId,
  kotNumber
) => {
  const existingRecord = await dbTransaction.salesHoldingReceiptNumber
    .where("[shopId+registerId]")
    .equals([parseInt(shopId), parseInt(registerId)])
    .first();

  const receiptData = {
    shopId: parseInt(shopId),
    registerId: parseInt(registerId),
    localSaleId: parseInt(localSaleId),
    kotNumber: parseInt(kotNumber),
  };

  if (existingRecord) {
    // Update existing record
    await dbTransaction.salesHoldingReceiptNumber.put(receiptData);
  } else {
    // Add new record
    await dbTransaction.salesHoldingReceiptNumber.add(receiptData);
  }

  return receiptData;
};

export const getSaleHoldingReceiptNumber = async (shopId, registerId) => {
  return await dbTransaction.salesHoldingReceiptNumber
    .where("[shopId+registerId]")
    .equals([parseInt(shopId), parseInt(registerId)])
    .first();
};
export const initTransactionDb = async () => {
  return await dbTransaction.open();
};

export const updateSalesHoldingData = async (saleObj) => {
  return await dbTransaction.salesHolding.put(saleObj);
};

export const getTransactionDataByKey = async (tableName, keyName, keyValue) => {
  return await dbTransaction[tableName]
    .where(keyName)
    .anyOf(keyValue)
    .toArray();
};