import { useEffect, useState, useRef } from "react";
import { FaBolt } from "react-icons/fa";
import Tooltip from "@mui/material/Tooltip";

export default function ShortCutKeys({
  shortCutKeysChild = <></>,
  hideExistingKeys = false,
}) {
  const keysRef = useRef(null);
  const [showShortCutKey, setShowShortCutKey] = useState(false);
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (keysRef.current && !keysRef.current.contains(event.target)) {
        setShowShortCutKey(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);
  return (
    <div
      className="keysContainer"
      onClick={() => setShowShortCutKey(!showShortCutKey)}
      ref={keysRef}
    >
      <Tooltip title="Shortcut Keys" placement="top">
        <div className="shortcutKeyContainer shortcutIcon">
          <FaBolt />
        </div>
      </Tooltip>
      {showShortCutKey && (
        <div className="shortCutKeysInfoContainer">
          <div className="shortCutKeysHeadContainer">Shortcut Keys</div>
          <div className="shortCutKeyDetailContainer">
            {!hideExistingKeys && (
              <>
                <div className="shortCutKeyText">
                  1. Save. Same <strong>{"{F8}"}</strong> or{" "}
                  <strong>{"{ALT+S}"}</strong> key will be used to save Item.
                </div>
                <div className="shortCutKeyText">
                  2. Update. Same <strong>{"{F7}"}</strong> or{" "}
                  <strong>{"{ALT+U}"}</strong> key will be used to update Item
                  (opened in edit mode).
                </div>
                <div className="shortCutKeyText">
                  3. <strong>{"{ALT+D}"}</strong> will be used to delete Item.
                </div>
              </>
            )}
            <>{shortCutKeysChild}</>
          </div>
        </div>
      )}
    </div>
  );
}
